function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) {
  if (v === true) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
function hasValidJson(v) {
  const s = safeStr(v);
  if (!s || s === '{}' || s === 'null') return false;
  try {
    const p = JSON.parse(s);
    return p && typeof p === 'object' && !Array.isArray(p);
  } catch (e) { return false; }
}

const nav = $('Nav laden').first().json;
const MAX_VORGAENGE = 100;
const allRows = $input.all().map(i => i.json || {});
// FIX 2026-07-28 (Nutzerfrage "es waren aber schon 2 gepostet", P8b zeigte 0/98 trotz 3
// echten Veroeffentlichungen): MAX_VORGAENGE schnitt bisher nicht nur die Detailtabelle,
// sondern ALLE Aggregat-Kennzahlen (total, countIf, sharepicWanted, ...) auf die neuesten
// 100 Vorgaenge zurecht - sobald die Tabelle diese Grenze ueberschritt, fielen die AELTESTEN
// Zeilen (z.B. per P1-Rueckstands-Backfill nachtraeglich eingefuegte alte Vorlagen wie
// 2026/098/100/103) aus JEDER Prozentanzeige komplett heraus, obwohl sie laengst fertig und
// veroeffentlicht waren. Aggregat-Kennzahlen laufen jetzt ueber ALLE Zeilen; der Cap gilt nur
// noch fuer die Detailtabelle weiter unten (detailCandidates).
const rows = allRows;
const total = rows.length;

function countIf(fn) { return rows.filter(fn).length; }

function isNextcloudDone(r) {
  const f = safeStr(r.nextcloudFolder);
  return !!(f && f.toLowerCase() !== 'null' && f !== '-');
}
function isBewertungDone(r) {
  return safeStr(r.summaryText).length >= 50 &&
    hasValidJson(r.analysisJson) &&
    safeStr(r.lastAnalysisAt).length > 0;
}
const nextcloudDone = countIf(isNextcloudDone);
const bewertungDone = countIf(isBewertungDone);

// FIX 2026-07-25: contentCreatedAt wird von P4 bei JEDEM Versuch gesetzt (Erfolg UND
// Fehlschlag) und sagt nichts darueber aus, ob echter Satire-Content erzeugt wurde - ersetzt
// durch eine ehrliche Reaktion-Stufe, die tatsaechlichen Content prueft.
// P5/P6/P8/P8b/P9 (Visual/Bild/diePARTEI/Mastodon) laufen tatsaechlich nur fuer die
// Sharepic-Kohorte (sharepicNeedStage=topic_ok) - dafuer bleibt sharepicTotal richtig.
// FIX 2026-07-26: P4 (Reaktion/Text) ist KEIN Teil dieser Kohorte - die Text-Reaktion
// entsteht laut P4 ("Pruefe Content-Freigabe") fuer topic_ok UND fuer not_applicable/
// topic_error gleichermassen, nur watching/ignored/noch-nicht-bewertete Vorgaenge bekommen
// nie eine Reaktion. Bisher zeigte das Dashboard z.B. "5/6" (nur die Sharepic-Kohorte)
// statt der tatsaechlich richtigen Zahl gegen alle Reaktion-faehigen Vorgaenge - Realfall
// 2026-07-26 vom Nutzer bemerkt ("muesste man das nicht 5/30 sehen?").
const sharepicWanted = rows.filter(r => safeStr(r.sharepicNeedStage) === 'topic_ok');
const sharepicTotal = sharepicWanted.length;
function countIfWanted(fn) { return sharepicWanted.filter(fn).length; }
// FIX 2026-07-26 (Nutzerfrage "ist 5/40 richtig?"): sharepicTotal allein beantwortet nicht,
// wie viele Vorgaenge der Eignungs-Agent ueberhaupt schon bearbeitet hat - davon sind die
// meisten typischerweise not_applicable, nicht topic_ok. Getrennt sichtbar machen.
const eignungsAgentDone = rows.filter(r => safeStr(r.sharepicNeedStage).length > 0).length;

const REAKTION_EXCLUDED_STAGES = new Set(['watching', 'ignored', '']);
const contentEligible = rows.filter(r => isBewertungDone(r) && !REAKTION_EXCLUDED_STAGES.has(safeStr(r.contentStage)));
const contentEligibleTotal = contentEligible.length;
function countIfContentEligible(fn) { return contentEligible.filter(fn).length; }

// FIX 2026-07-27 (Nutzerfrage "warum gehts bei den Reaktionen nicht weiter?"): websiteArticle/
// pressStatement werden NUR fuer die volle Artikel-Kette (i.d.R. sharepicNeedStage=topic_ok)
// befuellt. Bei not_applicable/topic_error laeuft die Satire-Kette trotzdem durch und schreibt
// echten Reaktionstext nach satireBrief (+ satirePunchlines etc.), landet aber nie in
// websiteArticle/pressStatement - Realfall: 51 als "offen" angezeigte Vorgaenge hatten
// tatsaechlich alle einen gefuellten satireBrief, 39 davon waren sogar schon auf WordPress
// veroeffentlicht. satireBrief zusaetzlich pruefen deckt beide Reaktionspfade ab.
function isReaktionDone(r) {
  if (safeStr(r.websiteArticle).length > 20 || safeStr(r.pressStatement).length > 20) return true;
  // FIX 2026-07-28 (Nutzerfrage "dann stimmt die 107/107 nicht?"): der satireBrief-Fallback
  // von 2026-07-27 war fuer den vereinfachten not_applicable/topic_error-Pfad gedacht, hatte
  // aber keine Sperre gegen topic_ok - satireBrief wird schon VOR P4 geschrieben (bei der
  // Kernbotschaft-Auswahl in P5b), nicht erst danach. Live bestaetigt: 12 von 12 aktuell
  // offenen topic_ok-Zeilen (9x awaiting_kernbotschaft, 3x needs_content) wurden dadurch
  // faelschlich als fertig gezaehlt, obwohl P4 sie nie angefasst hat.
  if (safeStr(r.sharepicNeedStage) === 'topic_ok') return false;
  return safeStr(r.satireBrief).length > 20;
}
function isVisualPromptDone(r) { return safeStr(r.imagePrompt).length > 0; }
// FIX 2026-07-27 (Nutzerfrage "dann darf die Statusuebersicht mir nur fertige Bilder
// zaehlen"): imageFinalPath wird schon VOR der Bildpruefung gesetzt (beim Compositing) -
// bei qa_failed oder einem zurueckgesetzten/fehlgeschlagenen frueheren Versuch blieb der
// Pfad stehen, obwohl nie ein tatsaechlich fertiges, freigegebenes Bild existiert (Realfall:
// 2026/157 endete qa_failed, 2026/098/100/103 blieben not_started, alle 4 hatten trotzdem
// einen gesetzten imageFinalPath). imageStage='composed' ist der einzige echte Erfolgs-
// Endzustand, den P6 nach abgeschlossener Pruefung schreibt.
function isBildDone(r) { return safeStr(r.imageStage) === 'composed'; }
// 2026-07-27 (Nutzerwunsch): eigener Zaehler fuer endgueltig missglueckte Bildversuche -
// qa_failed ist der einzige Endzustand, den P6 nach Ausschoepfung aller Neuversuche/
// Reparaturschleifen fuer einen gescheiterten Versuch schreibt (nicht zu verwechseln mit
// not_started, das nur "noch nicht dran" bedeutet).
function isBildFailed(r) { return safeStr(r.imageStage) === 'qa_failed'; }
// 2026-07-27 (Nutzerpraezisierung: "mit missglueckt meine ich jeden Versuch, auch die
// waehrend des Prozesses verworfenen"): P6 protokolliert JEDEN Bildversuch (auch die
// per Neuversuch verworfenen) in visualJson.qualityControl.history/attemptsUsed - das
// zaehlt alle tatsaechlichen OpenAI-Bildgenerierungen, nicht nur den finalen Endzustand.
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v)); return p && typeof p === 'object' && !Array.isArray(p) ? p : {}; } catch (e) { return {}; }
}
function getBildVersuche(r) {
  const qc = parseObj(r.visualJson).qualityControl;
  if (!qc) return 0;
  return Number(qc.attemptsUsed) || (Array.isArray(qc.history) ? qc.history.length : 0);
}
const reaktionDone = countIfContentEligible(isReaktionDone);
const p2Done = countIfWanted(isVisualPromptDone);
const p3Done = countIfWanted(isBildDone);
const p3Failed = countIfWanted(isBildFailed);
const bildVersucheGesamt = sharepicWanted.reduce((sum, r) => sum + getBildVersuche(r), 0);
const versucheProBild = p3Done > 0 ? (bildVersucheGesamt / p3Done) : 0;

// FIX 2026-07-27 (Nutzerfrage "sind die Zahlen fuer golietz.de richtig?"): P7 selbst
// (Filter WordPress-Kandidaten) schliesst Zeilen mit contentStage='needs_summary' oder
// contentStage='error' + einem der Fehlergruende analysis_error/summary_input_error/
// summary_parse_error dauerhaft aus - diese koennen NIE auf WordPress erscheinen, bis das
// zugrundeliegende Problem behoben ist. Der Nenner 'total' zaehlte sie trotzdem mit (68/90
// suggerierte 22 offene Vorgaenge, real waren 0 aktuell postbereit und noch nicht gepostet -
// die 22 waren 10 strukturell blockiert + 12 warten noch auf P4). Gleiche Fehlerklasse wie
// der P4-Denominator-Fix vom 2026-07-26.
const WORDPRESS_BLOCKED_ERROR_REASONS = new Set(['analysis_error', 'summary_input_error', 'summary_parse_error']);
function isWordpressBlocked(r) {
  const contentStage = safeStr(r.contentStage);
  return contentStage === 'needs_summary' || (contentStage === 'error' && WORDPRESS_BLOCKED_ERROR_REASONS.has(safeStr(r.contentErrorReason)));
}
const wordpressEligibleTotal = total - countIf(isWordpressBlocked);
const wordpressDone = countIf(r => safeBool(r.wordpressPosted));
const wordpressGoslarDone = countIf(r => safeBool(r.wordpressGoslarPosted));
// 2026-07-26: P8 legt seitdem sofort Entwuerfe an, ein separater taeglicher Schritt
// (P8b) veroeffentlicht davon nur einen pro Tag - Entwurf != veroeffentlicht, beides
// getrennt sichtbar machen statt wie bisher nur 'fertig'/'fehlt'.
// FIX 2026-07-26: P8/P8b/P9 sind (P9 seit heute) NICHT auf die Sharepic-Kohorte beschraenkt -
// alle drei verlangen nur echten P4-Content (websiteArticle/instagramCaption), warten auf ein
// Bild nur zusaetzlich bei topic_ok. Denominator ist reaktionDone (wer echten Content hat, kann
// hier ankommen), nicht sharepicTotal - gleiche Korrektur wie bei P4 oben.
const wordpressGoslarDraftDone = countIfContentEligible(r => safeStr(r.wordpressGoslarDraftId).length > 0 && !safeBool(r.wordpressGoslarPosted));
const mastodonDone = countIfContentEligible(r => safeBool(r.mastodonPosted));
const instagramDone = countIfWanted(r => safeBool(r.instagramPosted));
const facebookDone = countIfContentEligible(r => safeBool(r.facebookPosted));
const paperlessDone = countIf(r => safeStr(r.paperlessBackfilledAt).length > 0);

function esc(s) {
  return safeStr(s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function pct(n, denom) { denom = denom === undefined ? total : denom; return denom > 0 ? Math.round((n / denom) * 100) : 0; }

// FEATURE 2026-07-31 (Nutzerfrage "wie viele Vorgaenge sich in welchem Prozess befinden"):
// Verteilungs-Histogramme ueber die zentralen Stage-Felder - im Gegensatz zur Stufen-Tabelle
// oben (die nur "erledigt ja/nein" je Stufe zeigt) macht das sichtbar, WO die noch offenen
// Vorgaenge gerade stecken (z.B. wie viele bei awaiting_kernbotschaft vs. needs_content).
// FIX 2026-08-01 (Nutzerwunsch): 'leer' bei headlineChoiceStage/visualPromptStage/imageStage
// bedeutet meistens nicht "offen/unbearbeitet", sondern "kein Sharepic gewuenscht"
// (sharepicNeedStage=not_applicable) - diese Felder werden fuer solche Zeilen nie initialisiert.
// Undifferenziertes '(leer / offen)' sah im Dashboard wie ein Problem aus, obwohl es der
// erwartete Zustand fuer die Mehrheit der Vorgaenge ist. blankLabelFn erlaubt ein feldspezifisch
// sinnvolles Label statt des generischen Fallbacks.
// FIX 2026-08-01 Teil 2 (Nutzerfrage "sind die 95 not_started auch ohne Sharepic-Bedarf?"):
// imageStage bekommt seit heute den Default 'not_started' statt leer (siehe P4-Fix) - fuer
// not_applicable-Zeilen ist das genauso wenig "echte offene Arbeit" wie das vorherige Leer.
// valueLabelFn ersetzt blankLabelFn, wirkt jetzt auf JEDEN Wert (nicht nur Leerstring), damit
// 'not_started' bei not_applicable-Zeilen ebenfalls als "kein Sharepic nötig" zusammengefasst
// wird statt einen aufgeblaehten, groesstenteils irrelevanten not_started-Balken zu zeigen.
function histCounts(field, valueLabelFn) {
  const c = {};
  for (const r of rows) {
    const v = safeStr(r[field]);
    const label = valueLabelFn ? valueLabelFn(v, r) : (v === '' ? '(leer / offen)' : v);
    c[label] = (c[label] || 0) + 1;
  }
  return Object.entries(c).sort((a, b) => b[1] - a[1]);
}

const sharepicBlankLabel = (v, r) => v === '' ? (safeStr(r.sharepicNeedStage) === 'not_applicable' ? 'kein Sharepic nötig' : '(offen)') : v;
const imageStageLabel = (v, r) => (v === '' || v === 'not_started') && safeStr(r.sharepicNeedStage) === 'not_applicable'
  ? 'kein Sharepic nötig'
  : (v === '' ? '(offen)' : v);

function histTable(entries) {
  const rowsHtml = entries.map(([label, count]) =>
    '<tr><td>' + esc(label) + '</td><td>' + count + '</td><td>' +
    '<div class="bar"><div class="fill" style="width:' + pct(count, total) + '%"></div></div>' +
    '</td><td class="pct">' + pct(count, total) + '%</td></tr>'
  ).join('');
  return '<table class="hist-table"><tbody>' + rowsHtml + '</tbody></table>';
}

const STAGE_DISTRIBUTIONS = [
  { title: 'contentStage (P3/P4)', field: 'contentStage' },
  { title: 'sharepicNeedStage (P3d Eignungs-Agent)', field: 'sharepicNeedStage' },
  { title: 'headlineChoiceStage (Matrix-Auswahl)', field: 'headlineChoiceStage', blankLabel: sharepicBlankLabel },
  { title: 'visualPromptStage (P5)', field: 'visualPromptStage', blankLabel: sharepicBlankLabel },
  { title: 'imageStage (P6)', field: 'imageStage', blankLabel: imageStageLabel }
];

function stageRow(label, done, denom, schedule) {
  denom = denom === undefined ? total : denom;
  return '<tr><td>' + esc(label) + '</td><td class="schedule">' + esc(schedule || '') + '</td><td>' + done + ' / ' + denom + '</td><td>' +
    '<div class="bar"><div class="fill" style="width:' + pct(done, denom) + '%"></div></div>' +
    '</td><td class="pct">' + pct(done, denom) + '%</td></tr>';
}

// FEATURE 2026-08-01 (Nutzerfrage "das mit den leeren Feldern - haben wir das im Griff?"):
// Konsistenz-Pruefung ueber bekannte Stufe/Nutzdaten-Widersprueche. Jede "Stufe" (headlineChoiceStage,
// visualPromptStage, contentStage, sharepicNeedStage, imageStage) wird von anderem Code gesetzt als das
// dazugehoerige Nutzdaten-Feld - ohne DB-Constraint, die beide zusammenhaelt. Diese Session hat mehrfach
// denselben Bugtyp gefunden (vorlageDatum-Overwrite, visualPromptStage veraltet trotz fertigem Prompt,
// imageHeadline/imageSubline leer trotz headline_selected, sharepicNeedStage=topic_ok+contentStage=
// watching, ...). Diese Sektion macht kuenftige Faelle sichtbar, statt dass sie nur zufaellig beim
// Debuggen einer anderen Frage auffallen. Nur Anzeige, keine automatische Reparatur - die richtige
// Reparatur haengt vom Einzelfall ab (siehe Realfall 2026/189+190: Text nicht rekonstruierbar, Nutzer
// hat sich fuer Neu-Auswahl statt automatischem Fix entschieden).
const CONSISTENCY_RULES = [
  {
    id: 'headline_selected_but_empty_text',
    title: 'headlineChoiceStage=headline_selected, aber imageHeadline/imageSubline leer',
    check: r => safeStr(r.headlineChoiceStage) === 'headline_selected' &&
      (!safeStr(r.imageHeadline) || !safeStr(r.imageSubline))
  },
  {
    id: 'prompt_ready_but_no_prompt',
    title: 'visualPromptStage=prompt_ready, aber imagePrompt leer',
    check: r => safeStr(r.visualPromptStage) === 'prompt_ready' && !safeStr(r.imagePrompt)
  },
  {
    id: 'composed_but_no_prompt',
    title: 'imageStage=composed, aber imagePrompt leer',
    check: r => safeStr(r.imageStage) === 'composed' && !safeStr(r.imagePrompt)
  },
  {
    id: 'watching_but_topic_ok',
    title: 'contentStage=watching, aber sharepicNeedStage=topic_ok',
    check: r => safeStr(r.contentStage) === 'watching' && safeStr(r.sharepicNeedStage) === 'topic_ok'
  },
  {
    id: 'not_applicable_but_prompt_stage_open',
    title: 'sharepicNeedStage=not_applicable, aber visualPromptStage/headlineChoiceStage noch gesetzt',
    check: r => safeStr(r.sharepicNeedStage) === 'not_applicable' &&
      (!!safeStr(r.visualPromptStage) || !!safeStr(r.headlineChoiceStage))
  },
  // Nachtrag 2026-08-01 Teil 2 (Nutzerfrage "genauer" zu 2026/032+030+003): auch die
  // isReaktionDone()-Fassung war noch missverstanden - contentStage=content_posted heisst NUR
  // "P7 hat den neutralen golietz.de-Kurzfassungs-Post veroeffentlicht" (P7 baut seinen Content
  // IMMER nur aus summaryText, nie aus websiteArticle/pressStatement/satireBrief - andere Seite,
  // anderer Zweck als die DIE-PARTEI-Satire). P7 veroeffentlicht bewusst auch dann, wenn P4s
  // Satire-Content-Erzeugung fehlgeschlagen ist (contentStage='error', nicht blockierter Grund)
  // oder noch gar nicht drangekommen ist - das ist beabsichtigtes Fallback-Verhalten, kein Bug.
  // "content_posted ohne Text" ist also normal. Die tatsaechlich interessanten Faelle sind
  // spezifischer:
  {
    id: 'topic_ok_content_error',
    title: 'sharepicNeedStage=topic_ok, aber P4-Satire-Content-Erzeugung ist fehlgeschlagen (contentErrorReason=content_error)',
    check: r => safeStr(r.sharepicNeedStage) === 'topic_ok' && safeStr(r.contentErrorReason) === 'content_error'
  },
  {
    id: 'topic_ok_posted_before_p4',
    title: 'sharepicNeedStage=topic_ok, contentStage=content_posted, aber P4 hat contentCreatedAt nie gesetzt (P7 ist P4 zuvorgekommen, siehe FIX 2026-07-26 in P7)',
    check: r => safeStr(r.sharepicNeedStage) === 'topic_ok' && safeStr(r.contentStage) === 'content_posted' && !safeStr(r.contentCreatedAt)
  },
  {
    id: 'final_path_without_composed',
    title: 'imageFinalPath gesetzt, aber imageStage nicht composed/qa_failed',
    check: r => !!safeStr(r.imageFinalPath) && !['composed', 'qa_failed'].includes(safeStr(r.imageStage))
  }
];

const consistencyFindings = [];
for (const rule of CONSISTENCY_RULES) {
  for (const r of rows) {
    if (rule.check(r)) {
      consistencyFindings.push({
        vorgangsnummer: safeStr(r.vorgangsnummer) || safeStr(r.vorgangKey),
        rule: rule.title
      });
    }
  }
}

function consistencyTable() {
  if (consistencyFindings.length === 0) {
    return '<div class="empty">Keine bekannten Stufe/Nutzdaten-Widersprueche gefunden.</div>';
  }
  const rowsHtml = consistencyFindings.map(f =>
    '<tr><td>' + esc(f.vorgangsnummer) + '</td><td>' + esc(f.rule) + '</td></tr>'
  ).join('');
  return '<table class="detail-table"><thead><tr><th>Vorgangsnummer</th><th>Widerspruch</th></tr></thead><tbody>' + rowsHtml + '</tbody></table>';
}

// Detailtabelle 2026-07-25 (Nutzerwunsch): eine Zeile pro Vorgang (nur die, die tatsaechlich
// in Nextcloud existieren - nextcloudFolder gesetzt), Status jeder Stufe nebeneinander als
// Spalte. topic_ok-Vorgaenge (die, die DIE PARTEI tatsaechlich kommentiert) stehen oben und
// sind hervorgehoben, weil das der eigentlich interessante Teil der Pipeline ist - fuer alle
// anderen sind Reaktion/Visual/Bild/diePARTEI/Mastodon nicht zutreffend (na), nicht "fehlend".
function statusCell(state) {
  if (state === 'done') return '<td class="cell-done">✓</td>';
  if (state === 'draft') return '<td class="cell-draft">◐</td>';
  if (state === 'na') return '<td class="cell-na">–</td>';
  return '<td class="cell-pending">·</td>';
}

function detailRow(r) {
  const decided = safeStr(r.sharepicNeedStage).length > 0;
  const wantsSharepic = safeStr(r.sharepicNeedStage) === 'topic_ok';
  const nc = isNextcloudDone(r) ? 'done' : 'pending';
  const bw = isBewertungDone(r) ? 'done' : 'pending';
  const sp = !decided ? 'pending' : (wantsSharepic ? 'done' : 'na');
  // FIX 2026-07-26: Reaktion (Text) ist nicht auf die Sharepic-Kohorte beschraenkt, siehe oben.
  const contentEligibleRow = isBewertungDone(r) && !REAKTION_EXCLUDED_STAGES.has(safeStr(r.contentStage));
  const rk = !contentEligibleRow ? 'na' : (isReaktionDone(r) ? 'done' : 'pending');
  const vp = !wantsSharepic ? 'na' : (isVisualPromptDone(r) ? 'done' : 'pending');
  const bd = !wantsSharepic ? 'na' : (isBildDone(r) ? 'done' : 'pending');
  const wp = safeBool(r.wordpressPosted) ? 'done' : 'pending';
  // FIX 2026-07-27: dieselbe Kohorten-Beschraenkung wie bei rk oben - P8 (diePARTEI) und P9
  // (Mastodon) verlangen seit den Fixes vom 2026-07-26 keinen Sharepic mehr als Grundvoraussetzung
  // (nur echten Content), sondern nur zusaetzlich ein Bild fuer topic_ok-Vorgaenge. Diese Detail-
  // Spalten zeigten deshalb faelschlich "na" fuer bereits real angelegte diePARTEI-Entwuerfe/
  // Mastodon-Posts nicht-topic_ok-Vorgaenge (Nutzerfrage: "warum zeigt die Tabelle die
  // vorbereiteten Posts nicht an?").
  const wg = !contentEligibleRow ? 'na' : (safeBool(r.wordpressGoslarPosted) ? 'done' : (safeStr(r.wordpressGoslarDraftId).length > 0 ? 'draft' : 'pending'));
  const md = !contentEligibleRow ? 'na' : (safeBool(r.mastodonPosted) ? 'done' : 'pending');
  const ig = !wantsSharepic ? 'na' : (safeBool(r.instagramPosted) ? 'done' : 'pending');
  const fb = !contentEligibleRow ? 'na' : (safeBool(r.facebookPosted) ? 'done' : 'pending');
  const pl = safeStr(r.paperlessBackfilledAt).length > 0 ? 'done' : 'pending';
  return '<tr class="' + (wantsSharepic ? 'row-sharepic' : '') + '"><td>' + esc(r.vorgangsnummer) + '</td><td>' + esc(r.title).slice(0, 70) + '</td>' +
    statusCell(nc) + statusCell(bw) + statusCell(sp) + statusCell(rk) + statusCell(vp) + statusCell(bd) + statusCell(wp) + statusCell(wg) + statusCell(md) + statusCell(ig) + statusCell(fb) + statusCell(pl) +
    '</tr>';
}

// FIX 2026-08-28 (Nutzerfrage "es fehlen Facebook-Posts in der Liste"): vorher fielen aeltere
// text-only-Vorgaenge (nicht topic_ok) trotz erfolgtem Social-Post aus der auf MAX_VORGAENGE
// begrenzten Detailtabelle (lastseen 26.07. -> Platz 240+). Sortier-Reihenfolge jetzt:
//   1. topic_ok (die hell unterlegten Sharepic-Vorgaenge) - unveraendert oben
//   2. innerhalb dieser Stufe: echter Social-Post (Mastodon/Instagram/Facebook) zuerst
//   3. dann lastseen (neueste zuerst)
// Ausserdem waechst die Slice-Grenze bei Bedarf ueber MAX_VORGAENGE hinaus, so dass KEIN
// Vorgang mit Social-Post je abgeschnitten wird. ("veroeffentlicht ueberall" inkl. wordpress*
// taugt nicht - das ist bei 242/243 Zeilen gesetzt.)
function hasSocialPost(r) {
  return safeBool(r.mastodonPosted) || safeBool(r.instagramPosted) || safeBool(r.facebookPosted);
}
const _detailBase = rows.filter(isNextcloudDone).sort((a, b) => {
  const aWant = safeStr(a.sharepicNeedStage) === 'topic_ok' ? 1 : 0;
  const bWant = safeStr(b.sharepicNeedStage) === 'topic_ok' ? 1 : 0;
  if (aWant !== bWant) return bWant - aWant;
  const aSoc = hasSocialPost(a) ? 1 : 0;
